/* ═══════════════════════════════════════════════════════════════
   station-model.js — shared surface station plot for contextclimate.io
   ───────────────────────────────────────────────────────────────
   Used by surface-map.html; built so the Surface Analysis Builder
   can load it too (ghost rendering, wind-only mode, and thinning
   that re-runs on every render so it follows zoom/pan).

     • Parsing   — raw METAR first, NWS decoded JSON as fallback
     • Tendency  — 3-hr pressure change + WMO characteristic (0-8),
                   from the 5appp group when present, else computed
                   from hourly history
     • Glyph     — US/WMO station model: sky cover, wind barb,
                   T / Td / present weather / visibility on the left,
                   coded SLP / tendency on the right, gust at the
                   staff tip, station ID below
     • Thinning  — greedy, priority-ordered, box-based overlap test

   Public API (window.STATION_MODEL):
     ready()                         → Promise; resolves once fonts are usable
     fromNws(feature)                → normalized observation
     tendencyFromHistory(ob, obs[])  → { ppp, a, source } | null
     layout(ctx, ob, opts)           → { els, box } (box relative to station)
     thin(ctx, items, opts)          → { kept, dropped }  (opts: clip, reserved, layoutFn)
     draw(ctx, x, y, ob, opts)       → full model (opts.lay reuses a layout)
     drawThinned(ctx, x, y, opts)    → small marker for a thinned station
   opts: { windOnly, ghost, showId, halo }

   Present-weather and pressure-tendency symbols use a subset of the
   MetPy wx_symbols font (modified from the OGC MetOcean DWG World
   Weather Symbols, CC BY 4.0). The METAR → WMO ww mapping follows
   MetPy's wx_code_map (BSD 3-Clause).
   ═══════════════════════════════════════════════════════════════ */

window.STATION_MODEL = (function () {
  'use strict';

  // ── Visual tokens ──────────────────────────────────
  const COLORS = {
    ink:     '#1b1f24',
    temp:    '#c8322b',
    dew:     '#1d7f3b',
    id:      '#69717a',
    halo:    '#f7f6f2',          // matches map-base land so halos disappear on land
    disc:    '#f7f6f2',          // station circle interior
    thinned: 'rgba(27,31,36,0.42)',
    ghost:   'rgba(27,31,36,0.30)',
  };

  const WX_COLORS = {
    rain:    '#1f9448',
    snow:    '#2d6fd2',
    mix:     '#7a4fc9',
    ice:     '#cf3689',
    thunder: '#d8322a',
    obscur:  '#6f7780',
    dust:    '#96683a',
    other:   '#1b1f24',
  };

  const WX_FAMILY = 'CCWxSymbols';
  const FONTS = {
    data:  '600 16px "Barlow Condensed"',
    small: '600 13px "Barlow Condensed"',
    id:    '400 12px "Barlow Condensed"',
    wx:    `24px ${WX_FAMILY}`,     // nominal; see WX_MAX_H
    tend:  `14px ${WX_FAMILY}`,
  };

  const WX_PX = 24;      // present-weather symbol size
  const WX_MAX_H = 16;   // tallest symbol ink allowed between the T and Td rows

  // Geometry. R drives the layout; everything is in CSS px.
  const GEOM = {
    R:         6.5,   // station circle radius
    STAFF:     34,    // staff length, measured from the circle edge
    BARB:      13,    // full (10 kt) barb length
    SPACE:     5.5,   // spacing between barbs along the staff
    PENNANT:   6.5,   // pennant base width along the staff
    ANGLE:     60,    // barb angle off the staff, leaning toward the tip (deg)
    CALM_GAP:  3.5,   // calm ring distance outside the circle
    GAP:       5,     // circle edge → text column
    ROW:       15,    // vertical offset of the upper / lower rows
    LINE:      1.5,   // staff / barb stroke
    RING:      1.4,   // circle stroke
    HALO:      4,     // text halo stroke width
    GUST_OFF:  13,    // gust label distance beyond the staff tip
    THIN_PAD:  2,     // extra clearance between model boxes when thinning
  };

  // ── Weather-symbol font (subset, base64) ───────────
  const WX_FONT_B64 = '';

  // Code point per WMO ww 0–149 (offset from U+E900; −1 = no symbol).
  const WW_CP = [-1, -1, -1, -1, 162, 163, 164, 165, 168, 169, 170, 171, 172, 173, 174, 175, 176, 177, 178, 179, 180, 181, 182, 183, 184, 185, 186, 187, 188, 189, 190, 191, 192, 193, 194, 195, 196, 197, 198, 199, 200, 201, 202, 203, 204, 205, 206, 207, 208, 209, 210, 211, 212, 213, 214, 215, 216, 217, 218, 219, 220, 221, 222, 223, 224, 225, 226, 227, 228, 229, 230, 231, 232, 233, 234, 235, 236, 237, 238, 239, 240, 241, 242, 243, 244, 245, 246, 247, 248, 249, 250, 251, 252, 253, 256, 259, 262, 263, 266, 267, -1, -1, -1, 268, 79, 80, -1, -1, -1, -1, 81, 82, 83, -1, -1, -1, -1, -1, 84, -1, 85, 86, 87, 88, 89, 90, 91, 92, 93, 94, 95, 96, 97, 98, 99, 100, -1, -1, -1, -1, 101, 102, 103, 104, 105, 106, 107, 108, 109, 110];
  const TEND_CP0 = 0xE900; // pressure tendency a = 0…8

  let readyPromise = null;
  function ready() {
    if (readyPromise) return readyPromise;
    readyPromise = (async () => {
      try {
        const bin = atob(WX_FONT_B64);
        const bytes = new Uint8Array(bin.length);
        for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        const face = new FontFace(WX_FAMILY, bytes.buffer);
        await face.load();
        document.fonts.add(face);
      } catch (e) {
        console.warn('[station-model] weather symbol font failed to load', e);
      }
      try {
        await Promise.all([
          document.fonts.load(FONTS.data, '0123456789'),
          document.fonts.load(FONTS.small, 'G0'),
          document.fonts.load(FONTS.id, 'ABC'),
        ]);
      } catch { /* fall back to whatever is available */ }
    })();
    return readyPromise;
  }

  // ── METAR → WMO present weather (ww) ───────────────
  // From MetPy's wx_code_map. Values ≥1000 select an alternate symbol
  // (thousands digit) for the same ww — e.g. 1095 = TS with rain.
  const WX_CODE_MAP = {'': 0, 'M': 0, 'TSNO': 0, 'VA': 4, 'FU': 4,
    'HZ': 5, 'DU': 6, 'BLDU': 1007, 'SA': 1007, 'BLSA': 1007, 'VCBLSA': 1007, 'VCBLDU': 1007, 'BLPY': 1007,
    'PO': 8, 'VCPO': 8, 'VCDS': 9, 'VCSS': 9, 'BR': 10, 'BCBR': 10, 'BC': 11, 'MIFG': 12,
    'VCTS': 13, 'VIRGA': 14, 'VCSH': 16, 'TS': 17, 'THDR': 17, 'VCTSHZ': 17, 'TSFZFG': 17, 'TSBR': 17,
    'TSDZ': 17, 'VCTSUP': 17, '-TSUP': 17, 'TSUP': 17, '+TSUP': 17, 'SQ': 18, 'FC': 19, '+FC': 19,
    'DS': 31, 'SS': 31, 'DRSA': 31, 'DRDU': 31, '+DS': 34, '+SS': 34, 'DRSN': 36, '+DRSN': 37,
    '-BLSN': 38, 'BLSN': 38, '+BLSN': 39, 'VCBLSN': 38, 'VCFG': 40, 'BCFG': 41, 'PRFG': 44,
    'FG': 45, 'FZFG': 49, '-VCTSDZ': 51, '-DZ': 51, '-DZBR': 51, 'VCTSDZ': 53, 'DZ': 53, '+VCTSDZ': 55,
    '+DZ': 55, '-FZDZ': 56, '-FZDZSN': 56, 'FZDZ': 57, '+FZDZ': 57, 'FZDZSN': 57, '-DZRA': 58, 'DZRA': 59,
    '+DZRA': 59, '-RA': 61, '-RABR': 61, 'RA': 63, 'RABR': 63, 'RAFG': 63, 'VCRA': 63, '+RA': 65,
    '-FZRA': 66, '-FZRASN': 66, '-FZRABR': 66, '-FZRAPL': 66, '-FZRASNPL': 66, 'TSFZRAPL': 67,
    '-TSFZRA': 67, 'FZRA': 67, '+FZRA': 67, 'FZRASN': 67, 'TSFZRA': 67, '-DZSN': 68, '-RASN': 68,
    '-SNRA': 68, '-SNDZ': 68, 'RASN': 69, '+RASN': 69, 'SNRA': 69, 'DZSN': 69, 'SNDZ': 69, '+DZSN': 69,
    '+SNDZ': 69, '-SN': 71, '-SNBR': 71, 'SN': 73, '+SN': 75, '-SNSG': 77, 'SG': 77, '-SG': 77, 'IC': 78,
    '-FZDZPL': 79, '-FZDZPLSN': 79, 'FZDZPL': 79, '-FZRAPLSN': 79, 'FZRAPL': 79, '+FZRAPL': 79,
    '-RAPL': 79, '-RASNPL': 79, '-RAPLSN': 79, '+RAPL': 79, 'RAPL': 79, '-SNPL': 79, 'SNPL': 79,
    '-PL': 79, 'PL': 79, '-PLSN': 79, '-PLRA': 79, 'PLRA': 79, '-PLDZ': 79, '+PL': 79, 'PLSN': 79,
    'PLUP': 79, '+PLSN': 79, '-SH': 80, '-SHRA': 80, 'SH': 81, 'SHRA': 81, '+SH': 81, '+SHRA': 81,
    '-SHRASN': 83, '-SHSNRA': 83, '+SHRABR': 84, 'SHRASN': 84, '+SHRASN': 84, 'SHSNRA': 84,
    '+SHSNRA': 84, '-SHSN': 85, 'SHSN': 86, '+SHSN': 86, '-GS': 87, '-SHGS': 87, 'FZRAPLGS': 88,
    '-SNGS': 88, 'GSPLSN': 88, 'GSPL': 88, 'PLGSSN': 88, 'GS': 88, 'SHGS': 88, '+GS': 88, '+SHGS': 88,
    '-GR': 89, '-SHGR': 89, '-SNGR': 90, 'GR': 90, 'SHGR': 90, '+GR': 90, '+SHGR': 90,
    '-TSRASN': 95, 'TSRASN': 95, '-TSSNRA': 95, 'TSSNRA': 95, '-VCTSRA': 1095, '-TSRA': 1095,
    'TSRA': 1095, '-TSDZ': 1095, 'VCTSRA': 1095, 'TSPL': 2095, '-TSSN': 2095, '-TSPL': 2095,
    'TSSN': 2095, '-VCTSSN': 2095, 'VCTSSN': 2095, 'TSPLSN': 2095, 'TSSNPL': 2095, '-TSSNPL': 2095,
    '-TSRAGR': 96, 'TSRAGS': 96, 'TSRAGR': 96, 'TSGS': 96, 'TSGR': 96, '+TSFZRAPL': 97,
    '+VCTSRA': 1097, '+TSRA': 1097, '+TSFZRA': 1097, '+TSSN': 2097, '+TSPL': 2097, '+TSPLSN': 2097,
    '+VCTSSN': 2097, 'TSSA': 98, 'TSDS': 98, 'TSDU': 98, '+TSGS': 99, '+TSGR': 99, '+TSRAGS': 99,
    '+TSRAGR': 99, 'IN': 141, '-UP': 141, 'UP': 141, '+UP': 142, '-FZUP': 147, 'FZUP': 147, '+FZUP': 148,
  };

  // Same fallback MetPy uses: try progressively shorter prefixes.
  function wxTokenCode(tok) {
    if (tok in WX_CODE_MAP) return WX_CODE_MAP[tok];
    const opts = /^[-+]/.test(tok)
      ? [[0, 7], [0, 5], [1, 5], [0, 3], [1, 3]]
      : [[0, 6], [0, 4], [0, 2]];
    for (const [a, b] of opts) {
      const s = tok.slice(a, b);
      if (s in WX_CODE_MAP) return WX_CODE_MAP[s];
    }
    return 0;
  }

  // WMO precedence: the highest ww among reported groups.
  function wxCode(tokens) {
    let best = 0;
    for (const t of tokens || []) {
      const c = wxTokenCode(t);
      if (c % 1000 > best % 1000) best = c;
    }
    return best % 1000 > 0 ? best : null;
  }

  function wxClass(code) {
    const c = code % 1000;
    if (c === 13 || (c >= 17 && c <= 19) || (c >= 91 && c <= 99)) return 'thunder';
    if (c === 56 || c === 57 || c === 66 || c === 67 || c === 79 || (c >= 87 && c <= 90) || c === 147 || c === 148) return 'ice';
    if (c === 68 || c === 69 || c === 83 || c === 84 || c === 141 || c === 142) return 'mix';
    if ((c >= 36 && c <= 39) || (c >= 70 && c <= 78) || c === 85 || c === 86) return 'snow';
    if ((c >= 50 && c <= 65) || (c >= 80 && c <= 82) || (c >= 14 && c <= 16)) return 'rain';
    if ((c >= 4 && c <= 9) || (c >= 30 && c <= 35)) return 'dust';
    if ((c >= 10 && c <= 12) || (c >= 40 && c <= 49)) return 'obscur';
    return 'other';
  }

  function wxChar(code) {
    const base = code % 1000, alt = Math.floor(code / 1000);
    const off = WW_CP[base];
    if (off == null || off < 0) return null;
    return String.fromCharCode(0xE900 + off + alt);
  }

  // ── METAR parsing ──────────────────────────────────
  const WX_RE = /^(?:[-+]|VC)?(?:VC)?(?:MI|PR|BC|DR|BL|SH|TS|FZ){0,2}(?:DZ|RA|SN|SG|IC|PL|GR|GS|UP|BR|FG|FU|VA|DU|SA|HZ|PY|PO|SQ|FC|SS|DS)*$/;
  const isWxToken = t => t.length >= 2 && WX_RE.test(t) && /[A-Z]{2}/.test(t);

  const frac = s => { const [n, d] = s.split('/').map(Number); return d ? n / d : NaN; };
  const tempTok = s => s == null ? null : (s[0] === 'M' ? -Number(s.slice(1)) : Number(s));

  function parseMetar(raw) {
    if (!raw || typeof raw !== 'string') return null;
    const text = raw.replace(/\s+/g, ' ').trim().replace(/=$/, '');
    const cut = text.search(/\sRMK(\s|$)/);
    const body = cut >= 0 ? text.slice(0, cut) : text;
    const rmk  = cut >= 0 ? text.slice(cut + 5) : '';
    const t = body.split(' ');

    const o = { wind: null, visSM: null, visLT: false, wx: [], sky: [], tempC: null, dewC: null,
                altMb: null, slp: null, slpNO: false, tend5: null, auto: false };

    let i = 0;
    if (t[i] === 'METAR' || t[i] === 'SPECI') i++;
    if (/^[A-Z][A-Z0-9]{3}$/.test(t[i] || '')) i++;
    if (/^\d{6}Z$/.test(t[i] || '')) i++;
    else return null; // not a METAR we understand

    for (; i < t.length; i++) {
      const tok = t[i];
      let m;
      if (tok === 'AUTO') { o.auto = true; continue; }
      if (tok === 'COR' || tok === 'RTD') continue;
      if (!o.wind && (m = tok.match(/^(\d{3}|VRB)(\d{2,3})(?:G(\d{2,3}))?(KT|MPS)$/))) {
        const f = m[4] === 'MPS' ? 1.94384 : 1;
        o.wind = {
          dir:  m[1] === 'VRB' ? null : Number(m[1]) % 360,
          kt:   Math.round(Number(m[2]) * f),
          gust: m[3] != null ? Math.round(Number(m[3]) * f) : null,
        };
        if (m[1] === '000' && o.wind.kt === 0) o.wind.dir = null;
        continue;
      }
      if (/^\/{5}KT$/.test(tok)) continue;
      if (/^\d{3}V\d{3}$/.test(tok)) continue;
      if (tok === 'CAVOK') { o.visSM = 10; o.sky.push('CLR'); continue; }
      if (o.visSM == null && /^\d$/.test(tok) && /^\d\/\d{1,2}SM$/.test(t[i + 1] || '')) {
        o.visSM = Number(tok) + frac(t[i + 1].slice(0, -2)); i++; continue;
      }
      if (o.visSM == null && (m = tok.match(/^([MP])?(\d+\/\d+|\d+)SM$/))) {
        o.visSM = m[2].includes('/') ? frac(m[2]) : Number(m[2]);
        if (m[1] === 'M') o.visLT = true;
        continue;
      }
      if (/^R\d{2}[LCR]?\//.test(tok)) continue;             // RVR
      if (/^(CLR|SKC|NCD|NSC)$/.test(tok)) { o.sky.push('CLR'); continue; }
      if ((m = tok.match(/^(FEW|SCT|BKN|OVC)(\d{3}|\/{3})/))) { o.sky.push(m[1]); continue; }
      if (/^VV(\d{3}|\/{3})$/.test(tok)) { o.sky.push('VV'); continue; }
      if ((m = tok.match(/^(M?\d{2})\/(M?\d{2})?$/))) {
        o.tempC = tempTok(m[1]); o.dewC = tempTok(m[2]); continue;
      }
      if ((m = tok.match(/^A(\d{4})$/))) { o.altMb = Number(m[1]) / 100 * 33.8639; continue; }
      if ((m = tok.match(/^Q(\d{4})$/))) { o.altMb = Number(m[1]); continue; }
      if (isWxToken(tok)) { o.wx.push(tok); continue; }
    }

    for (const tok of rmk.split(' ')) {
      let m;
      if ((m = tok.match(/^SLP(\d{3})$/))) {
        const v = Number(m[1]) / 10;
        o.slp = Math.round((v < 50 ? 1000 + v : 900 + v) * 10) / 10;
      } else if (tok === 'SLPNO') {
        o.slpNO = true;
      } else if ((m = tok.match(/^T([01])(\d{3})([01])(\d{3})?$/))) {
        o.tempC = (m[1] === '1' ? -1 : 1) * Number(m[2]) / 10;
        if (m[4] != null) o.dewC = (m[3] === '1' ? -1 : 1) * Number(m[4]) / 10;
      } else if ((m = tok.match(/^5([0-8])(\d{3})$/))) {
        const a = Number(m[1]), amt = Number(m[2]);
        const sign = a === 4 ? 0 : (a >= 5 ? -1 : 1);
        o.tend5 = { a, ppp: sign * amt };
      }
    }
    return o;
  }

  // ── Normalization (NWS api.weather.gov feature → ob) ──
  const VIS_STEPS = [0, 1/16, 1/8, 3/16, 1/4, 5/16, 3/8, 1/2, 5/8, 3/4, 7/8, 1, 1.25, 1.5, 1.75,
                     2, 2.5, 3, 4, 5, 6, 7, 8, 9, 10];
  const snapVis = sm => VIS_STEPS.reduce((b, v) => Math.abs(v - sm) < Math.abs(b - sm) ? v : b, 0);
  const SKY_RANK = { CLR: 0, FEW: 1, SCT: 2, BKN: 3, OVC: 4, VV: 5 };

  function maxSky(list) {
    let best = null;
    for (const s0 of list || []) {
      const s = (s0 === 'SKC' || s0 === 'NCD' || s0 === 'NSC') ? 'CLR' : s0;
      if (!(s in SKY_RANK)) continue;
      if (best == null || SKY_RANK[s] > SKY_RANK[best]) best = s;
    }
    return best;
  }

  const val = q => (q && q.value != null && !Number.isNaN(q.value)) ? q.value : null;

  function fromNws(feat) {
    const p = feat.properties || {};
    const c = feat.geometry && feat.geometry.coordinates;
    const m = parseMetar(p.rawMessage);

    // Wind
    let wind = m && m.wind ? m.wind : null;
    if (!wind) {
      const kmh = val(p.windSpeed), dir = val(p.windDirection), g = val(p.windGust);
      if (kmh != null) {
        const kt = Math.round(kmh / 1.852);
        wind = { dir: kt === 0 ? null : dir, kt, gust: g != null ? Math.round(g / 1.852) : null };
      }
    }

    // Visibility (statute miles)
    let visSM = m ? m.visSM : null, visLT = m ? m.visLT : false;
    if (visSM == null && val(p.visibility) != null) visSM = snapVis(val(p.visibility) / 1609.344);

    // Present weather
    let wx = m ? m.wx : [];
    if ((!m || !m.wx.length) && Array.isArray(p.presentWeather) && p.presentWeather.length) {
      wx = p.presentWeather.map(w => (w.rawString || '').trim()).filter(Boolean);
    }

    // Sky cover
    const skyList = m && m.sky.length ? m.sky
      : (Array.isArray(p.cloudLayers) ? p.cloudLayers.map(l => l.amount) : []);

    // Pressure — true SLP only (METAR SLP remark or its decoded value).
    let slp = m ? m.slp : null;
    if (slp == null && !(m && m.slpNO) && val(p.seaLevelPressure) != null) {
      slp = Math.round(val(p.seaLevelPressure) / 10) / 10;
    }
    let altMb = m ? m.altMb : null;
    if (altMb == null && val(p.barometricPressure) != null) altMb = val(p.barometricPressure) / 100;

    return {
      lon: c ? c[0] : null,
      lat: c ? c[1] : null,
      ts:  p.timestamp || null,
      raw: p.rawMessage || '',
      tempC: m && m.tempC != null ? m.tempC : val(p.temperature),
      dewC:  m && m.dewC  != null ? m.dewC  : val(p.dewpoint),
      wind, visSM, visLT, wx,
      ww: wxCode(wx),
      sky: maxSky(skyList),
      slp, altMb,
      tend5: m ? m.tend5 : null,
      tend: null,
    };
  }

  // ── Pressure tendency ──────────────────────────────
  // WMO code table 0200 characteristic from four hourly values
  // p = [t−3h, t−2h, t−1h, t] (middle values may be null).
  function tendencyCode(p) {
    const netR = Math.round((p[3] - p[0]) * 10);
    if (p[1] == null || p[2] == null) return netR > 0 ? 2 : netR < 0 ? 7 : 4;
    const e = (p[1] - p[0]) + 0.5 * (p[2] - p[1]);   // first 1.5 h
    const l = 0.5 * (p[2] - p[1]) + (p[3] - p[2]);   // last 1.5 h
    const THR = 0.25;
    const cls = v => v > THR ? 1 : v < -THR ? -1 : 0;
    const E = cls(e), L = cls(l);
    if (netR > 0) {
      if (E === 1 && L === -1) return 0;
      if (E === 1 && L === 0)  return 1;
      if (E === 1 && L === 1)  return l < 0.5 * e ? 1 : l > 2 * e ? 3 : 2;
      if (E <= 0 && L === 1)   return 3;
      if (E === 0 && L === -1) return 0;
      return 2;
    }
    if (netR < 0) {
      if (E === -1 && L === 1)  return 5;
      if (E === -1 && L === 0)  return 6;
      if (E === -1 && L === -1) return l > 0.5 * e ? 6 : l < 2 * e ? 8 : 7;
      if (E >= 0 && L === -1)   return 8;
      if (E === 0 && L === 1)   return 5;
      return 7;
    }
    if (E === 1 && L === -1) return 0;
    if (E === -1 && L === 1) return 5;
    return 4;
  }

  // `hist` is any list of normalized obs for the same station.
  function tendencyFromHistory(now, hist) {
    if (!now || !now.ts) return null;
    if (now.tend5) return { ppp: now.tend5.ppp, a: now.tend5.a, source: 'metar' };
    const t0 = Date.parse(now.ts);
    const TOL = 15 * 60e3;
    const near = h => {
      const target = t0 - h * 3600e3;
      let best = null, bd = Infinity;
      for (const o of hist || []) {
        const d = Math.abs(Date.parse(o.ts) - target);
        if (d <= TOL && d < bd) { bd = d; best = o; }
      }
      return best;
    };
    const pts = [near(3), near(2), near(1), now];
    if (!pts[0]) return null;
    let key = null;
    if (pts[0].slp != null && now.slp != null) key = 'slp';
    else if (pts[0].altMb != null && now.altMb != null) key = 'altMb';
    if (!key) return null;
    const p = pts.map(o => (o && o[key] != null) ? o[key] : null);
    return { ppp: Math.round((p[3] - p[0]) * 10), a: tendencyCode(p), source: key };
  }

  // ── Formatting ─────────────────────────────────────
  const cToF = c => c == null ? null : Math.round(c * 9 / 5 + 32);
  const fmtSlp = mb => mb == null ? '' : String(Math.round(mb * 10) % 1000).padStart(3, '0');
  const fmtTend = ppp => ppp == null ? '' : (ppp > 0 ? '+' : ppp < 0 ? '-' : '') + String(Math.abs(ppp)).padStart(2, '0');

  const VIS_FRAC = { 0.25: '\u00BC', 0.5: '\u00BD', 0.75: '\u00BE' };
  function formatVis(sm, lt) {
    if (sm == null) return '';
    const whole = Math.floor(sm + 1e-9), f = Math.round((sm - whole) * 16) / 16;
    let s;
    if (f === 0) s = String(whole);
    else if (VIS_FRAC[f]) s = (whole ? whole : '') + VIS_FRAC[f];
    else {
      const n = f * 16; let num = n, den = 16;
      while (num % 2 === 0) { num /= 2; den /= 2; }
      s = (whole ? whole + ' ' : '') + num + '/' + den;
    }
    return (lt ? '<' : '') + s;
  }

  // ── Layout ─────────────────────────────────────────
  // Text/symbol elements positioned relative to the station centre, plus
  // the bounding box used for thinning. Barb and gust are drawn outside
  // the box on purpose — they point in the wind direction.
  function measureInk(ctx, font, s) {
    ctx.font = font;
    const m = ctx.measureText(s);
    const l = m.actualBoundingBoxLeft ?? 0, r = m.actualBoundingBoxRight ?? m.width;
    const a = m.actualBoundingBoxAscent ?? 8, d = m.actualBoundingBoxDescent ?? 0;
    return { l, r, a, d, w: l + r, h: a + d };
  }

  // Place ink so its bounding box has the given right/left/centre x and vertical centre y.
  function place(ink, anchorX, align, cy) {
    let x;
    if (align === 'right')       x = anchorX - ink.r;
    else if (align === 'center') x = anchorX - (ink.r - ink.l) / 2;
    else                         x = anchorX + ink.l;
    const y = cy + (ink.a - ink.d) / 2;
    const box = { x0: x - ink.l, x1: x + ink.r, y0: y - ink.a, y1: y + ink.d };
    return { x, y, box };
  }

  // Staff geometry for a wind direction, relative to the station centre.
  function staffGeom(dir) {
    const { R, STAFF } = GEOM;
    const rad = dir * Math.PI / 180;
    const dx = Math.sin(rad), dy = -Math.cos(rad);   // toward where the wind comes from
    return { dx, dy, sx: dx * R, sy: dy * R, tx: dx * (R + STAFF), ty: dy * (R + STAFF) };
  }

  // Staff + barbs as a segment, and the gust label, used by thinning and drawing.
  function windParts(ctx, ob) {
    const w = ob.wind;
    let seg = null, gust = null;
    if (w && w.kt > 0 && w.dir != null) {
      const g = staffGeom(w.dir);
      const ext = GEOM.BARB * 0.5;
      seg = [g.sx, g.sy, g.tx + g.dx * ext, g.ty + g.dy * ext];
      if (w.gust != null && w.gust > w.kt) {
        const text = 'G' + w.gust;
        const ink = measureInk(ctx, FONTS.small, text);
        const pl = place(ink, g.tx + g.dx * GEOM.GUST_OFF, 'center', g.ty + g.dy * GEOM.GUST_OFF);
        gust = { text, x: pl.x, y: pl.y, box: pl.box };
      }
    }
    return { seg, gust };
  }

  function layout(ctx, ob, opts = {}) {
    const { R, GAP, ROW } = GEOM;
    const els = [];
    const box = { x0: -R - 1, x1: R + 1, y0: -R - 1, y1: R + 1 };
    const grow = b => { box.x0 = Math.min(box.x0, b.x0); box.x1 = Math.max(box.x1, b.x1);
                        box.y0 = Math.min(box.y0, b.y0); box.y1 = Math.max(box.y1, b.y1); };
    const add = (text, font, color, anchorX, align, cy) => {
      if (text === '' || text == null) return null;
      const ink = measureInk(ctx, font, String(text));
      const pl = place(ink, anchorX, align, cy);
      const el = { text: String(text), font, color, x: pl.x, y: pl.y, box: pl.box };
      els.push(el); grow(pl.box);
      return el;
    };

    if (opts.windOnly) return Object.assign({ els, box }, windParts(ctx, ob));

    const left = -(R + GAP), right = R + GAP;

    add(cToF(ob.tempC), FONTS.data, COLORS.temp, left, 'right', -ROW);
    const tdEl = add(cToF(ob.dewC), FONTS.data, COLORS.dew, left, 'right', ROW);
    const wp = windParts(ctx, ob);

    // Present weather, right-aligned to the left text column, mid row.
    let visAnchor = left;
    // Tall symbols (thunderstorm, showers) are scaled to fit between the
    // T and Td rows.
    if (ob.ww != null) {
      const ch = wxChar(ob.ww);
      if (ch) {
        const ink = measureInk(ctx, FONTS.wx, ch);
        const px = WX_PX * Math.min(1, WX_MAX_H / Math.max(ink.h, 1));
        const el = add(ch, `${px.toFixed(1)}px ${WX_FAMILY}`, WX_COLORS[wxClass(ob.ww)], left, 'right', 0);
        if (el) visAnchor = el.box.x0 - 3;
      }
    }

    // Visibility only when restricted (≤ 6 SM).
    if (ob.visSM != null && ob.visSM <= 6) {
      add(formatVis(ob.visSM, ob.visLT), FONTS.data, COLORS.ink, visAnchor, 'right', 0);
    }

    if (ob.slp != null) add(fmtSlp(ob.slp), FONTS.data, COLORS.ink, right, 'left', -ROW);

    if (ob.tend) {
      const el = add(fmtTend(ob.tend.ppp), FONTS.data, COLORS.ink, right, 'left', 0);
      const sym = String.fromCharCode(TEND_CP0 + ob.tend.a);
      const s = add(sym, FONTS.tend, COLORS.ink, (el ? el.box.x1 : right) + 2, 'left', 0);
      if (s) s.weight = 0.7;   // heavier than the barbs so it doesn't read as one
    }

    // Station ID below the circle: nudged right to clear the dewpoint, and
    // moved to the right of the staff when a southerly wind runs through it.
    if (opts.showId !== false && ob.id) {
      const text = ob.id.length === 4 && ob.id[0] === 'K' ? ob.id.slice(1) : ob.id;
      const ink = measureInk(ctx, FONTS.id, text);
      const hw = ink.w / 2, cy = R + 9;
      let cx = 0;
      if (tdEl) cx = Math.max(cx, tdEl.box.x1 + 7 + hw);
      const xs = segXInBand(wp.seg, cy - ink.h / 2 - 2, cy + ink.h / 2 + 2);
      if (xs && xs.min < cx + hw + 3 && xs.max > cx - hw - 3) cx = xs.max + 4 + hw;
      add(text, FONTS.id, COLORS.id, cx, 'center', cy);
    }

    // VRB wind has no staff; its label sits above the circle.
    const w = ob.wind;
    if (w && w.dir == null && w.kt >= 3) {
      add(`VRB ${w.kt}${w.gust ? ' G' + w.gust : ''}`, FONTS.small, COLORS.ink, 0, 'center', -(ROW + 13));
    }

    return Object.assign({ els, box }, wp);
  }

  // x-extent of a segment where it passes through the horizontal band y0..y1.
  function segXInBand(seg, y0, y1) {
    if (!seg) return null;
    const [ax, ay, bx, by] = seg;
    const n = Math.max(2, Math.ceil(Math.hypot(bx - ax, by - ay)));
    let min = Infinity, max = -Infinity;
    for (let i = 0; i <= n; i++) {
      const x = ax + (bx - ax) * i / n, y = ay + (by - ay) * i / n;
      if (y >= y0 && y <= y1) { if (x < min) min = x; if (x > max) max = x; }
    }
    return min <= max ? { min, max } : null;
  }

  // ── Thinning ───────────────────────────────────────
  // items: [{ x, y, ob, priority }] in screen px. Lower priority number wins.
  // A model is dropped if its text box overlaps an accepted model's text box,
  // or if either one's staff / gust label runs into the other's text box.
  // opts.clip     {x0,y0,x1,y1} — models must fit entirely inside it
  // opts.reserved [{x0,y0,x1,y1}] — areas no model may cover (stamp, buttons)
  // opts.layoutFn (item) → { box, seg?, gust? } to thin something other than
  //               the station model (e.g. single-value labels)
  const hitBox = (a, b) => a.x0 < b.x1 && a.x1 > b.x0 && a.y0 < b.y1 && a.y1 > b.y0;
  function hitSeg(seg, b) {
    if (!seg) return false;
    const [x0, y0, x1, y1] = seg;
    const n = Math.max(2, Math.ceil(Math.hypot(x1 - x0, y1 - y0) / 3));
    for (let i = 0; i <= n; i++) {
      const x = x0 + (x1 - x0) * i / n, y = y0 + (y1 - y0) * i / n;
      if (x > b.x0 && x < b.x1 && y > b.y0 && y < b.y1) return true;
    }
    return false;
  }
  const shift = (b, x, y, p) => b && ({ x0: x + b.x0 - p, x1: x + b.x1 + p, y0: y + b.y0 - p, y1: y + b.y1 + p });

  function thin(ctx, items, opts = {}) {
    const pad = GEOM.THIN_PAD;
    const order = items.map((it, i) => ({ it, i }))
      .sort((a, b) => (a.it.priority ?? 9) - (b.it.priority ?? 9) || a.i - b.i);
    const taken = [], kept = [], dropped = [];
    const reserved = opts.reserved || [];
    for (const { it } of order) {
      const lay = opts.layoutFn ? opts.layoutFn(it) : layout(ctx, it.ob, opts);
      const box  = shift(lay.box, it.x, it.y, pad);
      const gust = lay.gust ? shift(lay.gust.box, it.x, it.y, 1) : null;
      const seg  = lay.seg ? [it.x + lay.seg[0], it.y + lay.seg[1], it.x + lay.seg[2], it.y + lay.seg[3]] : null;
      const c = opts.clip;
      const outside = c && (box.x0 < c.x0 || box.x1 > c.x1 || box.y0 < c.y0 || box.y1 > c.y1);
      const blocked = outside || reserved.some(r => hitBox(box, r) || (gust && hitBox(gust, r)))
        || taken.some(t => hitBox(box, t.box) || hitSeg(seg, t.box) || (gust && hitBox(gust, t.box))
                        || hitSeg(t.seg, box) || (t.gust && hitBox(t.gust, box)));
      if (blocked) dropped.push(it);
      else { taken.push({ box, seg, gust }); kept.push(Object.assign({}, it, { lay })); }
    }
    return { kept, dropped };
  }

  // ── Drawing ────────────────────────────────────────
  function colorFor(c, opts) { return opts.ghost ? COLORS.ghost : c; }

  function drawSky(ctx, x, y, sky, opts) {
    const { R, RING } = GEOM;
    const ink = colorFor(COLORS.ink, opts);
    ctx.save();
    ctx.beginPath(); ctx.arc(x, y, R, 0, Math.PI * 2);
    if (!opts.ghost) { ctx.fillStyle = COLORS.disc; ctx.fill(); }

    ctx.fillStyle = ink;
    const wedge = (a1) => {
      ctx.beginPath(); ctx.moveTo(x, y);
      ctx.arc(x, y, R, -Math.PI / 2, -Math.PI / 2 + a1);
      ctx.closePath(); ctx.fill();
    };
    if (sky === 'FEW') wedge(Math.PI / 2);
    else if (sky === 'SCT') wedge(Math.PI);
    else if (sky === 'BKN') wedge(Math.PI * 1.5);
    else if (sky === 'OVC') { ctx.beginPath(); ctx.arc(x, y, R, 0, Math.PI * 2); ctx.fill(); }

    ctx.strokeStyle = ink; ctx.lineWidth = RING;
    ctx.beginPath(); ctx.arc(x, y, R, 0, Math.PI * 2); ctx.stroke();

    if (sky === 'VV') {
      const d = R * 0.7071;
      ctx.lineWidth = 1.2; ctx.lineCap = 'round';
      ctx.beginPath();
      ctx.moveTo(x - d, y - d); ctx.lineTo(x + d, y + d);
      ctx.moveTo(x + d, y - d); ctx.lineTo(x - d, y + d);
      ctx.stroke();
    } else if (sky == null) {
      // Missing: an "M" drawn as strokes so it stays crisp at this size.
      const u = R * 0.48;
      ctx.lineWidth = 1.1; ctx.lineJoin = 'miter'; ctx.lineCap = 'butt';
      ctx.beginPath();
      ctx.moveTo(x - u, y + u); ctx.lineTo(x - u, y - u);
      ctx.lineTo(x, y + u * 0.35); ctx.lineTo(x + u, y - u); ctx.lineTo(x + u, y + u);
      ctx.stroke();
    }
    ctx.restore();
  }

  function haloText(ctx, text, x, y, font, color, opts, weight) {
    ctx.font = font;
    ctx.textAlign = 'left';
    ctx.textBaseline = 'alphabetic';
    if (opts.halo !== false && !opts.ghost) {
      ctx.lineWidth = GEOM.HALO + (weight || 0); ctx.lineJoin = 'round';
      ctx.strokeStyle = COLORS.halo;
      ctx.strokeText(text, x, y);
    }
    ctx.fillStyle = colorFor(color, opts);
    ctx.fillText(text, x, y);
    if (weight) {
      ctx.lineWidth = weight; ctx.strokeStyle = colorFor(color, opts);
      ctx.strokeText(text, x, y);
    }
  }

  function drawWind(ctx, x, y, ob, opts, lay) {
    const w = ob.wind;
    if (!w || w.kt == null) return;
    const { R, BARB, SPACE, PENNANT, ANGLE, CALM_GAP, LINE } = GEOM;
    const ink = colorFor(COLORS.ink, opts);
    ctx.save();
    ctx.strokeStyle = ink; ctx.fillStyle = ink;
    ctx.lineWidth = LINE; ctx.lineCap = 'round'; ctx.lineJoin = 'round';

    if (w.kt === 0) {
      ctx.lineWidth = GEOM.RING;
      ctx.beginPath(); ctx.arc(x, y, R + CALM_GAP, 0, Math.PI * 2); ctx.stroke();
      ctx.restore(); return;
    }
    if (w.dir == null) { ctx.restore(); return; } // VRB — label handled in layout()

    const g = staffGeom(w.dir);
    const dx = g.dx, dy = g.dy;
    const px = -dy, py = dx;                         // barb side (Northern Hemisphere)
    const ca = Math.cos(ANGLE * Math.PI / 180), sa = Math.sin(ANGLE * Math.PI / 180);
    const vx = BARB * (ca * dx + sa * px), vy = BARB * (ca * dy + sa * py);

    const sx = x + g.sx, sy = y + g.sy;
    const tx = x + g.tx, ty = y + g.ty;
    ctx.beginPath(); ctx.moveTo(sx, sy); ctx.lineTo(tx, ty); ctx.stroke();

    const kt5 = Math.round(w.kt / 5) * 5;
    let n50 = Math.floor(kt5 / 50), rem = kt5 - n50 * 50;
    let n10 = Math.floor(rem / 10); rem -= n10 * 10;
    const n5 = rem >= 5 ? 1 : 0;

    let pos = (n50 === 0 && n10 === 0 && n5 === 1) ? SPACE : 0;   // lone half barb set in from the tip
    const at = d => [tx - dx * d, ty - dy * d];

    for (let k = 0; k < n50; k++) {
      const [ox, oy] = at(pos), [ix, iy] = at(pos + PENNANT);
      ctx.beginPath();
      ctx.moveTo(ox, oy); ctx.lineTo(ix + vx, iy + vy); ctx.lineTo(ix, iy);
      ctx.closePath(); ctx.fill(); ctx.stroke();
      pos += PENNANT;
    }
    if (n50) pos += 1.5;
    for (let k = 0; k < n10; k++) {
      const [bx, by] = at(pos);
      ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx + vx, by + vy); ctx.stroke();
      pos += SPACE;
    }
    if (n5) {
      const [bx, by] = at(pos);
      ctx.beginPath(); ctx.moveTo(bx, by); ctx.lineTo(bx + vx * 0.5, by + vy * 0.5); ctx.stroke();
    }
    ctx.restore();

    const gust = lay && lay.gust ? lay.gust : windParts(ctx, ob).gust;
    if (gust) haloText(ctx, gust.text, x + gust.x, y + gust.y, FONTS.small, COLORS.ink, opts);
  }

  function draw(ctx, x, y, ob, opts = {}) {
    const lay = opts.lay || layout(ctx, ob, opts);
    ctx.save();
    drawWind(ctx, x, y, ob, opts, lay);
    drawSky(ctx, x, y, ob.sky, opts);
    for (const el of lay.els) haloText(ctx, el.text, x + el.x, y + el.y, el.font, el.color, opts, el.weight);
    ctx.restore();
    return lay;
  }

  function drawThinned(ctx, x, y, opts = {}) {
    ctx.save();
    ctx.beginPath(); ctx.arc(x, y, 2.5, 0, Math.PI * 2);
    ctx.fillStyle = opts.ghost ? COLORS.ghost : COLORS.thinned;
    ctx.fill();
    ctx.restore();
  }

  // Human-readable pieces for tooltips.
  const SKY_LABEL = { CLR: 'Clear', FEW: 'Few', SCT: 'Scattered', BKN: 'Broken', OVC: 'Overcast', VV: 'Sky obscured' };
  const TEND_LABEL = ['Rising, then falling', 'Rising, then steady or slower', 'Rising',
                      'Rising faster, or steady/falling then rising', 'Steady', 'Falling, then rising',
                      'Falling, then steady or slower', 'Falling', 'Falling faster, or steady/rising then falling'];

  return {
    COLORS, WX_COLORS, FONTS, GEOM, SKY_LABEL, TEND_LABEL,
    ready, parseMetar, fromNws, tendencyFromHistory, tendencyCode,
    wxCode, wxClass, wxChar, cToF, fmtSlp, fmtTend, formatVis,
    layout, thin, draw, drawThinned,
  };
})();
